using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterCoverageAttributeTests
{
    private const string TestSource = """
        using MessagePack;

        [MessagePackObject]
        public sealed class MapSample
        {
            [Key(0)]
            public int Value { get; set; }

            [Key(1)]
            public SampleEnum EnumValue { get; set; }
        }

        [MessagePackObject(true)]
        public sealed class StringKeySample
        {
            public int Value { get; set; }
        }

        public enum SampleEnum
        {
            Zero,
            One,
        }

        [Union(0, typeof(UnionSample))]
        public interface IUnionSample
        {
        }

        [MessagePackObject]
        public sealed class UnionSample : IUnionSample
        {
            [Key(0)]
            public int Value { get; set; }
        }
        """;

    [Fact]
    public async Task AllGeneratedFormattersAreDecorated_WithoutAnySetting()
    {
        var generation = await GenerateAsync(TestSource);
        var generatedTypes = GetGeneratedTypes(generation.GeneratedSources);

        generatedTypes.Should().NotBeEmpty();
        foreach (var type in generatedTypes)
        {
            HasExcludeFromCodeCoverage(type).Should().BeTrue(
                $"generated type {type.Identifier.ValueText} should be excluded from code coverage without any opt-in setting");
        }
    }

    [Theory]
    [InlineData("NETSTANDARD2_0")]
    [InlineData("NETFRAMEWORK")]
    public async Task GeneratedFormattersCompileWithoutAttributeOnUnsupportedTargets(string targetFrameworkSymbol)
    {
        var generation = await GenerateAsync(TestSource, targetFrameworkSymbol);

        generation.GeneratedSources.Should().NotBeEmpty();
        foreach (var generatedSource in generation.GeneratedSources)
        {
            generatedSource.SourceText.ToString().Should().NotContain(
                "ExcludeFromCodeCoverage",
                "the attribute must be conditionally omitted where it is unavailable");
        }
    }

    private static async Task<(GeneratedSourceResult[] GeneratedSources, ImmutableArray<Diagnostic> Diagnostics)> GenerateAsync(
        string source,
        params string[] preprocessorSymbols)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.CSharp7_3, preprocessorSymbols: preprocessorSymbols);
        var frameworkReferences = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = frameworkReferences.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        var compilation = CSharpCompilation.Create(
            "FormatterCoverageReceipt",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(
            compilation,
            out Compilation outputCompilation,
            out ImmutableArray<Diagnostic> generatorDiagnostics);

        var generatedSources = driver.GetRunResult().Results.SelectMany(result => result.GeneratedSources).ToArray();
        var errors = outputCompilation.GetDiagnostics()
            .AddRange(generatorDiagnostics)
            .Where(diagnostic => diagnostic.Severity == DiagnosticSeverity.Error)
            .Select(diagnostic => diagnostic.ToString())
            .ToArray();
        errors.Should().BeEmpty("the source and generated code should compile");
        return (generatedSources, generatorDiagnostics);
    }

    private static TypeDeclarationSyntax[] GetGeneratedTypes(GeneratedSourceResult[] generatedSources)
    {
        return generatedSources
            .SelectMany(generatedSource => generatedSource.SyntaxTree.GetRoot()
                .DescendantNodes()
                .OfType<TypeDeclarationSyntax>())
            .ToArray();
    }

    private static bool HasExcludeFromCodeCoverage(TypeDeclarationSyntax type)
    {
        return type.AttributeLists
            .SelectMany(list => list.Attributes)
            .Any(attribute => attribute.Name.ToString().EndsWith("ExcludeFromCodeCoverage", StringComparison.Ordinal));
    }
}

